import {activeSources} from './reconstruction-core.js';
import {clarificationItems,clarificationCandidates,clarificationLabels,historicalSource} from './clarification.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderClarifications(ledger,lang,{busy=false,drafts={}}={}){
  const c=clarificationLabels(lang),sources=activeSources(ledger),live=new Map(sources.map(s=>[s.id,s])),tasks=clarificationItems(ledger),candidates=clarificationCandidates(ledger,lang);
  const disabled=busy?'disabled':'',full=ledger.sources.length>=40;
  const ref=r=>{
    const old=historicalSource(ledger,r),now=live.get(r.id);
    const source=s=>`<p class="meta">${esc(s.author)} · ${esc(s.id)} v${s.version} · ${esc(s.recordedAt)}</p><blockquote>${esc(s.text)}</blockquote>`;
    return `<div class="clarification-evidence">${!now?`<p class="note">${esc(c.removed)}</p>`:now.version!==old.version?`<p class="note">${esc(c.changed)}</p><p class="meta">${esc(c.historical)}</p>`:''}${source(old)}${now&&now.version!==old.version?`<p class="meta">${esc(c.current)}</p>${source(now)}`:''}</div>`;
  };
  const counts=['open','answered','recheck','reviewed'].map(s=>`<span>${esc(c[s])} <b>${tasks.filter(q=>q.status===s).length}</b></span>`).join('');
  return `<section class="panel clarification-notebook" id="clarification-notebook"><p class="meta">${esc(c.version)}</p><h2>${esc(c.title)}</h2><p>${esc(c.intro)}</p><div class="clarification-counts">${counts}</div><p class="meta">${esc(c.scope)}</p>
  <details class="clarification-compose" ${drafts.question?'open':''}><summary>${esc(c.new)}</summary><form id="clarification-question"><fieldset ${disabled}><label>${esc(c.question)}<textarea name="question" required maxlength="1000">${esc(drafts.question||'')}</textarea></label><fieldset><legend>${esc(c.choose)}</legend>${sources.map(s=>`<label class="consent"><input type="checkbox" name="refs" value="${esc(s.id)}" ${(drafts.refs||[]).includes(s.id)?'checked':''}><span>${esc(s.author)} · ${esc(s.id)} v${s.version}<br>${esc(s.text.slice(0,180))}</span></label>`).join('')}</fieldset><button type="submit" ${!sources.length?'disabled':''}>${esc(c.save)}</button></fieldset></form></details>
  <details><summary>${esc(c.suggestions)} (${candidates.length})</summary>${candidates.map((q,i)=>`<article><p>${esc(q.question)}</p>${q.refs.map(ref).join('')}<button type="button" data-action="keep-question" data-index="${i}" ${disabled}>${esc(c.keep)}</button></article>`).join('')||`<p>${esc(c.none)}</p>`}</details>
  ${!tasks.length?`<p>${esc(c.empty)}</p>`:''}${[...tasks].sort((a,b)=>(a.status==='reviewed')-(b.status==='reviewed')).map(q=>`<article class="clarification-card ${q.status}" id="question-${esc(q.id)}"><p class="clarification-status">${esc(c[q.status])}</p><h3>${esc(q.question)}</h3><details ${q.status==='recheck'?'open':''}><summary>${esc(c.original)}</summary>${q.refs.map(ref).join('')}</details><details ${q.answers.length?'open':''}><summary>${esc(c.reply)} (${q.answers.length})</summary>${q.answers.map(ref).join('')}</details>
  <details ${drafts[q.id]?.text||drafts[q.id]?.author?'open':''}><summary>${esc(c.answer)}</summary><form class="clarification-answer" data-id="${esc(q.id)}"><fieldset ${busy||full?'disabled':''}><label>${esc(c.author)}<input name="replyAuthor" required maxlength="80" value="${esc(drafts[q.id]?.author||'')}"></label><label>${esc(c.words)}<textarea name="replyText" required maxlength="5000">${esc(drafts[q.id]?.text||'')}</textarea></label><button type="submit">${esc(c.submit)}</button></fieldset>${full?`<p class="note">${esc(c.full)}</p>`:''}</form></details>
  <p class="meta">${esc(c.hint)}</p><div class="toolbar"><button type="button" data-action="review-question" data-id="${esc(q.id)}" ${busy||q.status==='reviewed'||!q.answers.some(a=>live.has(a.id))?'disabled':''}>${esc(c.review)}</button>${q.reviews.at(-1)?.kind==='review'?`<button type="button" data-action="reopen-question" data-id="${esc(q.id)}" ${disabled}>${esc(c.reopen)}</button>`:''}</div>${q.reviews.length?`<p class="meta">${esc(c.at)}: ${esc(q.reviews.at(-1).at)}</p>`:''}</article>`).join('')}
  ${tasks.length?`<button type="button" data-action="export-questions" ${disabled}>${esc(c.export)}</button>`:''}</section>`;
}
